1	// 首页“创建公开房间”功能的界面回归测试。
2	//
3	// 与 main_test.go 的分工：main_test.go 通过公开 HTTP 接口验证创建与本地保存；
4	// 本文件用真实浏览器（系统 Chrome）加载真实服务的首页，模拟用户填写与提交，
5	// 断言用户在页面上实际看到的提示、表单与房间列表变化，重点区分两类请求结果：
6	//   1. POST /api/rooms 的创建结果（决定成功提示、编号与表单复位）；
7	//   2. 紧随其后的 GET /api/rooms 列表刷新结果（决定列表区域内容）。
8	// 两者不能混为一谈：创建被拒时列表不得新增记录；创建成功但列表刷新失败时，
9	// 成功提示与编号必须保留，列表区域必须显示加载失败而非“还没有房间记录”。
10	//
11	// 名称处理另有一组用例：页面提交前按与服务端一致的规则整理名称
12	// （去掉首尾 Unicode 空白、保留 U+FEFF、长度按码点计），这些用例必须区分
13	// “页面直接拦截（不发出创建请求）”与“请求发出后被服务端拒绝”，防止页面
14	// 放行错误名称、仅靠服务端兜底的情况被误判为符合要求。
15	//
16	// 运行：npm install && npm test（需要系统 Chrome，可用 CHROME_PATH 指定路径）。
17	
18	import { test, before, after } from 'node:test';
19	import assert from 'node:assert/strict';
20	import { execFile, spawn } from 'node:child_process';
21	import { mkdtemp, writeFile, rm } from 'node:fs/promises';
22	import { tmpdir } from 'node:os';
23	import path from 'node:path';
24	import { promisify } from 'node:util';
25	import puppeteer from 'puppeteer-core';
26	
27	const repoRoot = import.meta.dirname;
28	const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
29	
30	let serverBin;
31	let browser;
32	
33	// 与 main_test.go 相同的种子记录：带附带字段（note/tags/extra），
34	// 用于验证追加新房间时原有房间的内容与次序保持不变。
35	const SEED_ALPHA =
36	  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
37	  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z","note":"保留我","tags":["老友","周赛"]}';
38	const SEED_BETA =
39	  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
40	  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z","extra":{"rank":3}}';
41	
42	before(async () => {
43	  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
44	  serverBin = path.join(dir, 'score-arena');
45	  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
46	  browser = await puppeteer.launch({
47	    executablePath: chromePath,
48	    headless: true,
49	    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
50	  });
51	});
52	
53	after(async () => {
54	  if (browser) await browser.close();
55	  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
56	});
57	
58	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
59	function startServer(t, dataDir) {
60	  const proc = spawn(
61	    serverBin,
62	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
63	    { stdio: ['ignore', 'pipe', 'inherit'] },
64	  );
65	  t.after(() => { proc.kill('SIGKILL'); });
66	  return new Promise((resolve, reject) => {
67	    let buf = '';
68	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
69	    proc.stdout.on('data', (chunk) => {
70	      buf += chunk.toString();
71	      const m = buf.match(/listening on (http:\/\/\S+)/);
72	      if (m) {
73	        clearTimeout(timer);
74	        resolve(m[1]);
75	      }
76	    });
77	    proc.on('exit', (code) => {
78	      clearTimeout(timer);
79	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
80	    });
81	  });
82	}
83	
84	async function seedRooms(dataDir, ...records) {
85	  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + records.join(',\n') + '\n]\n');
86	}
87	
88	// 每个用例使用独立的数据目录、服务进程与页面，互不影响。
89	async function setupPage(t) {
90	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
91	  t.after(() => rm(dataDir, { recursive: true, force: true }));
92	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
93	  const baseURL = await startServer(t, dataDir);
94	  const page = await browser.newPage();
95	  t.after(() => page.close());
96	  await page.goto(baseURL, { waitUntil: 'load' });
97	  await waitForRowCount(page, 2);
98	  return { page, baseURL };
99	}
100	
101	function waitForRowCount(page, n) {
102	  return page.waitForFunction(
103	    (want) => document.querySelectorAll('#list-area table tbody tr').length === want,
104	    { timeout: 10000 },
105	    n,
106	  );
107	}
108	
109	function waitForMessageKind(page, kind) {
110	  return page.waitForFunction(
111	    (cls) => document.getElementById('form-msg').classList.contains(cls),
112	    { timeout: 10000 },
113	    kind,
114	  );
115	}
116	
117	// readRows 读取列表每一行的单元格文本、创建时间单元格的 title（原始 ISO 时间）
118	// 以及状态列徽标文本，用于逐格比对内容与次序。
119	function readRows(page) {
120	  return page.$$eval('#list-area table tbody tr', (trs) =>
121	    trs.map((tr) => {
122	      const tds = [...tr.querySelectorAll('td')];
123	      return {
124	        cells: tds.map((td) => td.textContent),
125	        timeTitle: tds[6] ? tds[6].getAttribute('title') : null,
