535	// 只含一个 U+FEFF 的名称是合法的一字符名称：不能因看起来没有可见文字就判空。
536	test('仅含一个 U+FEFF 的名称是合法的一字符名称', { timeout: 60000 }, async (t) => {
537	  const { page } = await setupPage(t);
538	  const postBodies = trackRoomPosts(page);
539	  const createdPromise = nextCreated(page);
540	
541	  const initialRows = await readRows(page);
542	  assertSeedRows(initialRows);
543	
544	  await fillGomokuForm(page, '\uFEFF', 0);
545	  await page.click('#submit');
546	
547	  // 页面不得把 U+FEFF 当成空白判空，应正常发出创建请求并成功。
548	  await waitForMessageKind(page, 'ok');
549	  const created = await createdPromise;
550	  assert.equal(postBodies.length, 1, 'U+FEFF 名称不应被页面拦截');
551	  assert.equal(JSON.parse(postBodies[0]).name, '\uFEFF');
552	  assert.equal(created.name, '\uFEFF', 'U+FEFF 应保留并计入长度');
553	
554	  const msg = await readMessage(page);
555	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id);
556	
557	  await waitForRowCount(page, 3);
558	  const rows = await readRows(page);
559	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
560	  assert.equal(rows[2].cells[1], '\uFEFF', '列表应原样展示 U+FEFF 名称');
561	});
562	
563	// 长度按 Unicode 码点计：中文与补充平面表情各算 1 个。整理后恰好 40 个码点可创建；
564	// 原始输入因两端空白超过 40 个码点时不应被页面提前拦截。
565	test('长度按码点计：恰好 40 码点（含表情）可创建，原始输入超长不提前拦截', { timeout: 60000 }, async (t) => {
566	  const { page } = await setupPage(t);
567	  const postBodies = trackRoomPosts(page);
568	  const createdPromise = nextCreated(page);
569	
570	  const initialRows = await readRows(page);
571	  assertSeedRows(initialRows);
572	
573	  // 39 个中文 + 1 个补充平面表情 = 40 个码点（JS 字符串长度为 41，字节数更多，
574	  // 用来防止按浏览器字符串长度或字节数误判）。
575	  const name40 = '棋'.repeat(39) + '🀄';
576	  assert.equal([...name40].length, 40);
577	  // 两端再加空白（普通空格、U+00A0、U+0085），原始输入超过 40 个码点，
578	  // 但整理后恰好 40，必须放行。
579	  const rawName = ' \u00A0\u00A0' + name40 + '\u0085 ';
580	  assert.ok([...rawName].length > 40, '原始输入应因两端空白超过 40 个码点');
581	
582	  await fillGomokuForm(page, rawName, 0);
583	  await page.click('#submit');
584	
585	  await waitForMessageKind(page, 'ok');
586	  const created = await createdPromise;
587	  assert.equal(postBodies.length, 1, '整理后恰好 40 码点不应被页面拦截');
588	  assert.equal(JSON.parse(postBodies[0]).name, rawName, '请求体应保留用户原始输入');
589	  assert.equal(created.name, name40, '服务端应去掉两端空白后保存 40 码点名称');
590	  assert.equal([...created.name].length, 40);
591	
592	  const msg = await readMessage(page);
593	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id);
594	
595	  await waitForRowCount(page, 3);
596	  const rows = await readRows(page);
597	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
598	  assert.equal(rows[2].cells[1], name40, '新行名称应为整理后的 40 码点名称');
599	  assert.equal(rows[2].cells[1], created.name);
600	});
601	
602	// 整理后为空的名称：页面直接拦截，明确提示不能为空，不发出创建请求、不显示
603	// 成功编号、不新增房间；已填内容保留，用户修正名称后按同一规则正常创建。
604	test('整理后为空的名称被页面拦截：不发请求、保留已填内容，修正后可创建', { timeout: 60000 }, async (t) => {
605	  const { page, baseURL } = await setupPage(t);
606	  const postBodies = trackRoomPosts(page);
607	
608	  const initialRows = await readRows(page);
609	  assertSeedRows(initialRows);
610	
611	  // 名称只含会被去掉的首尾空白（普通空格、U+00A0、U+0085），整理后为空。
612	  const blankName = ' \u00A0\u00A0\u0085 ';
613	  await fillGomokuForm(page, blankName, 0);
614	  await page.click('#submit');
615	
616	  // 页面直接拦截：显示页面自己的提示（与服务端文案不同，可据此区分拦截方）。
617	  await waitForMessageKind(page, 'error');
618	  const msg = await readMessage(page);
619	  assert.equal(msg.text, '房间名称不能为空。', '应显示页面侧的空名称提示');
620	  assert.ok(!msg.className.includes('ok'), '被拦截时不应显示成功提示');
621	  assert.ok(!msg.text.includes(SUCCESS_PREFIX), '被拦截时不应出现成功编号');
622	
623	  // 关键区分：这是页面直接拦截，必须没有发出任何创建请求；
624	  // 若请求被发出、仅靠服务端拒绝，本断言会失败。
625	  await new Promise((resolve) => setTimeout(resolve, 300));
626	  assert.equal(postBodies.length, 0, '页面拦截时不应发出创建请求');
627	  assert.equal((await readServerRooms(baseURL)).length, 2, '服务端不应新增记录');
628	
629	  // 已填写的名称与其他配置保留，按钮未被卡在等待状态，列表保持原样。
630	  assert.deepEqual(await readFormState(page), {
631	    name: blankName,
632	    game: 'gomoku',
633	    capacity: '2',
634	    capacityDisabled: false,
635	    turnSeconds: '0',
636	    submitDisabled: false,
637	  }, '被拦截后应保留已填内容');
638	  assert.deepEqual(await readRows(page), initialRows, '被拦截时不应改动房间列表');
639	
640	  // 用户直接修正名称（新名称同样带两端空白，按同一规则整理）即可成功创建。
641	  const createdPromise = nextCreated(page);
642	  await page.$eval('#name', (el) => { el.value = ''; });
643	  await page.type('#name', '  补录 棋室  ');
644	  await page.click('#submit');
645	
646	  await waitForMessageKind(page, 'ok');
647	  const created = await createdPromise;
648	  assert.equal(created.name, '补录 棋室', '修正后的名称应按同一规则整理');
649	  await waitForRowCount(page, 3);
650	  const rows = await readRows(page);
651	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
652	  assert.equal(rows[2].cells[1], '补录 棋室');
653	});
654	
655	// 整理后仍超过 40 个码点：页面直接拦截，明确提示超长，不发出创建请求、
656	// 不显示成功编号、不新增房间；已填内容保留，用户缩短名称后正常创建。
657	test('超过 40 码点的名称被页面拦截：不发请求、保留已填内容，修正后可创建', { timeout: 60000 }, async (t) => {
658	  const { page, baseURL } = await setupPage(t);
659	  const postBodies = trackRoomPosts(page);
660	
661	  const initialRows = await readRows(page);
662	  assertSeedRows(initialRows);
663	
664	  // 40 个中文 + 1 个补充平面表情 = 41 个码点（JS 字符串长度为 42），
665	  // 用来防止按浏览器字符串长度或字节数误判为未超长。
666	  const name41 = '棋'.repeat(40) + '🀄';
667	  assert.equal([...name41].length, 41);
668	  await fillGomokuForm(page, name41, 0);
669	  await page.click('#submit');
670	
671	  // 页面直接拦截：显示页面自己的超长提示（与服务端文案不同，可据此区分拦截方）。
672	  await waitForMessageKind(page, 'error');
673	  const msg = await readMessage(page);
674	  assert.equal(msg.text, '房间名称去掉首尾空白后不能超过 40 个字符。', '应显示页面侧的超长提示');
675	  assert.ok(!msg.className.includes('ok'), '被拦截时不应显示成功提示');
