677	
678	  // 关键区分：页面直接拦截，必须没有发出任何创建请求。
679	  await new Promise((resolve) => setTimeout(resolve, 300));
680	  assert.equal(postBodies.length, 0, '页面拦截时不应发出创建请求');
681	  assert.equal((await readServerRooms(baseURL)).length, 2, '服务端不应新增记录');
682	
683	  // 已填写的名称与其他配置保留，列表保持原样。
684	  assert.deepEqual(await readFormState(page), {
685	    name: name41,
686	    game: 'gomoku',
687	    capacity: '2',
688	    capacityDisabled: false,
689	    turnSeconds: '0',
